best=[]
for boundary in ['zero','edge','wrap']:
 for d1 in [(i,j) for i in range(-5,6) for j in range(-4,5)]:
  for d2 in [(i,j) for i in range(-5,6) for j in range(-4,5)]:
   if d1==d2:continue
   for op in ['and','or','xor','maj','nand','nor','xnor']:
    sc=tot=0
