     a=np.array([[int(c) for c in r] for r in inp]);o=np.array([[int(c) for c in r] for r in out]);h,w=a.shape
     b=np.zeros_like(a);c=np.zeros_like(a)
     for i in range(h):
      for j in range(w):
       vals=[]
       for di,dj in [d1,d2]:
        ii,jj=i+di,j+dj
        if boundary=='wrap':v=a[ii%h,jj%w]
        elif boundary=='edge':v=a[min(max(ii,0),h-1),min(max(jj,0),w-1)]
        else:v=a[ii,jj] if 0<=ii<h and 0<=jj<w else 0
